cat > merge.py <<'EOF'
import json, pandas as pd

MAP = {"user_id":"user_id","id":"user_id","userId":"user_id",
       "email":"email","email_address":"email",
       "full_name":"name","name":"name","userName":"name",
       "registration_date":"created_date","created_at":"created_date","joined":"created_date",
       "status":"status"}
BOOLS = {"is_active","active"}
FIELDS = ["name","email","created_date","status"]

def norm_date(v):
    if v is None or (isinstance(v,float) and pd.isna(v)): return None
    try: return pd.to_datetime(str(v)).strftime("%Y-%m-%d")
    except Exception: return str(v)

def to_bool(v):
    if isinstance(v,str): return v.strip().lower() in ("true","1","yes","y","t")
    return bool(v)

def normalize(df):
    recs = {}
    for r in df.to_dict("records"):
        out = {}
        for k,v in r.items():
            if k in MAP: out[MAP[k]] = v
            elif k in BOOLS and "status" not in out and not pd.isna(v):
                out["status"] = "active" if to_bool(v) else "inactive"
        if out.get("user_id") is None or pd.isna(out["user_id"]): continue
        out["user_id"] = int(out["user_id"])
        if "created_date" in out: out["created_date"] = norm_date(out["created_date"])
        for f in ("name","email","status"):
            if f in out and out[f] is not None and not (isinstance(out[f],float) and pd.isna(out[f])):
                out[f] = str(out[f]).strip()
            else: out[f] = None
        recs[out["user_id"]] = out
    return recs

srcs = {
 "source_a": normalize(pd.DataFrame(json.load(open("/data/source_a/users.json")))),
 "source_b": normalize(pd.read_csv("/data/source_b/users.csv", dtype=str)),
 "source_c": normalize(pd.read_parquet("/data/source_c/users.parquet")),
}
order = ["source_a","source_b","source_c"]
ids = sorted(set().union(*[s.keys() for s in srcs.values()]))
rows, conflicts = [], []
for uid in ids:
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {s: srcs[s][uid].get(f) for s in order if uid in srcs[s]}
        nn = {s:v for s,v in vals.items() if v is not None}
        sel = next(iter(nn.values()), None)
        row[f] = sel
        if len(set(nn.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": nn, "selected": sel})
    rows.append(row)
df = pd.DataFrame(rows, columns=["user_id"]+FIELDS)
df["user_id"] = df["user_id"].astype("int64")
for c in FIELDS: df[c] = df[c].astype("string")
df.to_parquet("/app/merged_users.parquet", index=False)
json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, open("/app/conflicts.json","w"), indent=2)
print(df); print(df.dtypes); print(json.dumps(conflicts, indent=1))
EOF
./envrun 'cat > /app/merge.py' < merge.py && ./envrun 'cd /app && python3 merge.py'
